3	import java.time.LocalDate;
4	import java.util.Objects;
5	import java.util.UUID;
6	
7	public class Book {
8	
9	    private final UUID id;
10	    private final String title;
11	    private BookStatus status;
12	
13	    private Book(UUID id, String title, BookStatus status) {
14	        this.id = Objects.requireNonNull(id, "id");
15	        if (title == null || title.isBlank()) {
16	            throw new IllegalArgumentException("title must not be blank");
17	        }
18	        this.title = title;
19	        this.status = Objects.requireNonNull(status, "status");
20	    }
21	
22	    public static Book register(String title) {
23	        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE);
24	    }
25	
26	    public static Book reconstitute(UUID id, String title, BookStatus status) {
27	        return new Book(id, title, status);
28	    }
29	
30	    public Loan loanTo(UUID memberId, LocalDate loanedAt) {
31	        if (status == BookStatus.ON_LOAN) {
